// Infinity / NaN are stored as strings in the JSON; restore them (only these exact strings).
function mt_dec(v) {
  if (v === 'Infinity') return Infinity;
  if (v === '-Infinity') return -Infinity;
  if (v === 'NaN') return NaN;
  if (Array.isArray(v)) return v.map(mt_dec);
  if (v && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, mt_dec(x)]));
  return v;
}

// Deep comparison of an actual value against the expected one (keys of the expected object only).
function mt_close(a, b, path, rel = 1e-6) {
  if (typeof b === 'number') {
    if (Number.isNaN(b)) { if (!Number.isNaN(a)) throw new Error(`${path}: expected NaN, got ${a}`); return; }
    if (!Number.isFinite(b)) { if (a !== b) throw new Error(`${path}: expected ${b}, got ${a}`); return; }
    if (typeof a !== 'number' || !(Math.abs(a - b) <= rel * Math.abs(b) + 1e-12)) throw new Error(`${path}: expected ${b}, got ${a}`);
    return;
  }
  if (b === null || typeof b !== 'object') {
    if (a !== b) throw new Error(`${path}: expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
    return;
  }
  if (Array.isArray(b)) {
    if (!a || a.length !== b.length) throw new Error(`${path}: length ${a && a.length} vs ${b.length}`);
    for (let i = 0; i < b.length; i++) mt_close(a[i], b[i], `${path}[${i}]`, rel);
    return;
  }
  if (!a || typeof a !== 'object') throw new Error(`${path}: expected an object, got ${a}`);
  for (const k of Object.keys(b)) mt_close(a[k], b[k], `${path}.${k}`, rel);
}

/*
 * One runner per parity section: maps the Python inputs onto the JS call. Returns the actual output in the
 * shape of the expected one.
 */
const MT_RUN = {
  local_parts: (i) => met_localParts(i.t),
  solar_elevation: (i) => solarElevation(i.t),
  stability_class: (i) => stabilityClass({ u10: i.u10, sw: i.sw, cloud: i.cloud, dateUTC: i.t }),
  obukhov_length: (i) => obukhovLength(i.cls, i.z0),
  mixing_height: (i) => mixingHeight({ cls: i.cls, blh: i.blh, mode: i.mode, hMin: i.hMin }),
  u_eff: (i) => uEff(i.u10, i.U0),
  direction_weights: (i) => Array.from(directionWeights(i.dir, i.u10)),
  turb_params: (i) => turbParams(i.cls, { z0: i.z0, d: i.d, Hbar: i.Hbar, h_eff: i.h_eff }),
  most: (i) => (i.turb ? MOST[i.fn](i.x, i.turb) : MOST[i.fn](i.x)),
  j_no2: (i) => jNO2(i.sw),
  k_no_o3: (i) => kNOO3(i.t),
  vector_mean_wind: (i) => vectorMeanWind(i.list),
  no2_chemistry: (i) => no2Chemistry(i),
  ppb: (i) => PPB[i.p],
  eaqi: (i) => eaqi(i.p, i.v, '1h', i.scheme),
  traffic_factor: (i) => trafficFactor(i.t, { month: i.month }),
  measure_factors: (i) => measureFactors(i.m),
  group_strengths: (i) => groupStrengths(i.p, i.t, i.m, { heating: i.heating, congestionShare: i.congestionShare }),
  increment: (i) => increment({ gamma: i.gamma, age: i.age, source: 'lut' }, i.q, i.u10, { beta: i.beta, U0: i.U0 }),
  metrics: (i) => metrics(i.obs, i.mod),
  mqi: (i) => mqi(i.obs, i.mod, i.p),
  chem_sample: (i) => no2Chemistry({ ...i, J: jNO2(i.sw), k: kNOO3(i.t2) }),   // real 2025 hours (J, k computed in JS)
};

test('models: parity with tools/aqmodel.py (all sections)', () => {
  assert(MT_PARITY && MT_PARITY.cases, 'parity vectors missing: run python3 tools/aqmodel.py --write-parity');
  const C = mt_dec(MT_PARITY.cases);
  const counts = {};
  for (const [sec, cases] of Object.entries(C)) {
    if (sec.startsWith('fallback')) continue;
    const run = MT_RUN[sec];
    assert(run, `no JS runner for parity section ${sec}`);
    cases.forEach((c, n) => mt_close(run(c.in), c.out, `${sec}#${n}`));
    counts[sec] = cases.length;
  }
  // Fallback: one model on the synthetic geometry, then its receptor and slice cases.
  const env = C.fallback_env[0].in.env;
  const fb = new FallbackModel(env);
  mt_close({ center: fb.center, n: fb.src.n, canyons: fb.canyons }, C.fallback_env[0].out, 'fallback_env');
  C.fallback_receptor.forEach((c, n) => mt_close(fb.receptor(c.in.dir, c.in.cls), c.out, `fallback_receptor#${n}`));
  C.fallback_slice.forEach((c, n) => mt_close(Array.from(fb.slice(c.in.dir, c.in.cls, c.in.height, c.in.grid)), c.out, `fallback_slice#${n}`));
  counts.fallback = C.fallback_receptor.length + C.fallback_slice.length + 1;
  return { generated: MT_PARITY.meta.generated_utc, counts, total: Object.values(counts).reduce((a, b) => a + b, 0) };
});

test('models: direction kernel sums to 1, peaks on the wind, uniform in calm', () => {
  for (const u of [0.5, 0.8, 1.3, 2, 4, 9]) {
    for (const d of [0, 11.25, 45, 200, 359]) {
      const w = directionWeights(d, u);
      assertClose(w.reduce((a, b) => a + b, 0), 1, 1e-6, `sum u=${u} d=${d}`);
      const jmax = w.indexOf(Math.max(...w));
      assert(Math.abs(angDiff(DIRS16[jmax], d)) <= 11.25 + 1e-9, `peak at ${DIRS16[jmax]} for ${d}`);
    }
  }
  const calm = directionWeights(120, 0.3);
  for (const v of calm) assertClose(v, 1 / 16, 1e-7, 'calm uniform');
  const s = directionWeights(90, 3);                        // symmetric about 90°
  assertClose(s[3], s[5], 1e-7, 'symmetry'); assertClose(s[0], s[8], 1e-7, 'symmetry');
  // σθ = 22.5° at U >= 2: the neighbour weight ratio is exp(-1/2)
  assertClose(s[5] / s[4], Math.exp(-0.5), 1e-6, 'σθ = 22.5°');
  // σθ = 60° cap at U = 0.5
  const c = directionWeights(0, 0.5);
  assertClose(c[1] / c[0], Math.exp(-(22.5 * 22.5) / (2 * 60 * 60)), 1e-6, 'σθ cap 60°');
});

test('models: stability tables (SRDT, Turner, Golder L, u*)', () => {
  const day = [[950, 1, 'A'], [950, 2.5, 'A'], [950, 4, 'B'], [950, 5.5, 'C'], [950, 7, 'C'],
    [700, 1, 'A'], [700, 2.5, 'B'], [700, 6, 'D'], [300, 1, 'B'], [300, 4, 'C'], [300, 5.5, 'D'], [100, 1, 'D']];
  for (const [G, u, c] of day) assert(stabilityClass({ u10: u, sw: G, cloud: 50 }) === c, `SRDT G=${G} u=${u} → ${c}`);
  const night = [[30, 1, 'F'], [30, 2.5, 'F'], [30, 4, 'E'], [30, 6, 'D'], [70, 1, 'F'], [70, 2.5, 'E'], [70, 4, 'D'], [100, 1, 'D']];
  for (const [cc, u, c] of night) assert(stabilityClass({ u10: u, sw: 0, cloud: cc }) === c, `Turner cc=${cc} u=${u} → ${c}`);
  assert(stabilityClass({ u10: NaN, sw: 500 }) === 'D', 'missing wind → D');
  // Night by the sun when sw is missing: 2025-01-15 00:00Z
  assert(stabilityClass({ u10: 1, cloud: 10, dateUTC: Date.UTC(2025, 0, 15, 0) }) === 'F', 'estimated night');
  assert(stabilityClass({ u10: 1, cloud: 0, dateUTC: Date.UTC(2025, 5, 21, 11) }) === 'A', 'estimated summer noon');
  // Golder L at z0' = 0.5 m (critic §1.13): A -9.6, B -22, C -135, E 106, F 22
  const L = { A: -9.6, B: -22, C: -135, E: 106, F: 22 };
  for (const [c, v] of Object.entries(L)) assertClose(obukhovLength(c, 0.5), v, Math.abs(v) * 0.03, `Golder ${c}`);
  assert(obukhovLength('D') === Infinity, 'neutral L = ∞');
  assertClose(obukhovLength('C', 1.5), obukhovLength('C', 0.5), 1e-12, 'z0 capped at 0.5 m');
  assert(stabilityGroup('A') === 'AC' && stabilityGroup('C') === 'AC' && stabilityGroup('D') === 'D' && stabilityGroup('F') === 'EF', 'groups');
  // u*/U10 neutral example of physics §6.2 (z0r 0.3, zb 80, d 8, z0 1.4) = 0.162
  assertClose(turbParams('D', { z0: 1.4, d: 8, Hbar: 14 }).ustar_hat, 0.162, 0.001, 'u* neutral');
  const tF = turbParams('EF'), tB = turbParams('AC');
  assert(tF.cls === 'F' && tB.cls === 'B' && tF.ustar_hat < turbParams('D').ustar_hat, 'stable u* smaller');
  assert(tF.h_eff >= 100 && tB.h_eff === 520, 'mixing heights by class');
  assert(MOST.kHatMO(200, turbParams('D', { h_eff: 135 })) === 0, 'K = 0 above the lid');
  assertClose(MOST.kHatMO(3, tB), MOST.kHatMO(14, tB), 1e-12, 'K constant below H̄');
  return { L: Object.fromEntries(MET_CLASSES.map((c) => [c, obukhovLength(c, 1.5)])), ustar: { B: tB.ustar_hat, D: turbParams('D').ustar_hat, F: tF.ustar_hat } };
});

test('models: mixing height floor and modes', () => {
  assert(mixingHeight({ cls: 'F', blh: 20, hMin: 100 }) === 100, 'floor 100');
  assert(mixingHeight({ cls: 'F', blh: 20, mode: 'nwp' }) === 20, 'raw NWP');
  assert(mixingHeight({ cls: 'F', blh: 5, mode: 'nwp' }) === 10, 'raw floor 10 m');
  assert(mixingHeight({ cls: 'F', blh: 200, mode: '315' }) === 315, 'AERMOD 315 m');
  assert(mixingHeight({ cls: 'B', blh: 900, mode: '315' }) === 900, 'above the floor');
  assert(mixingHeight({ cls: 'D', hMin: 100 }) === 135, 'class median when BLH is missing');
});

test('models: chemistry limits (NOx → 0, O3-limited titration, PSS, conservation)', () => {
  const k = kNOO3(15), J = jNO2(600);
  let r = no2Chemistry({ noxInc: 0, noxBg: 0, no2Bg: 0, o3Bg: 50, tau: 60, J, k });
  assertClose(r.no2, 0, 1e-9, 'NOx → 0 gives NO2 → 0'); assertClose(r.o3, 50, 1e-9, 'O3 unchanged');
  // O3-limited at night: all oxidant ends up as NO2 at long times
  r = no2Chemistry({ noxInc: 500, noxBg: 50, no2Bg: 20, o3Bg: 10, tau: Infinity, J: 0, k, fNO2: 0.1 });
  const X = 10 / PPB.o3 + 20 / PPB.no2 + 0.1 * 500 / PPB.no2;
  assertClose(r.no2, X * PPB.no2, 1e-9, 'titration NO2 = Ox'); assertClose(r.o3, 0, 1e-9, 'O3 used up');
  // NOx-limited at night: NO2 = NOx
  r = no2Chemistry({ noxInc: 2, noxBg: 3, no2Bg: 2, o3Bg: 80, tau: Infinity, J: 0, k });
  assertClose(r.no2, 5, 1e-9, 'NO2 = NOx when O3 is in excess');
  // PSS satisfies k (N - x)(X - x) = J x
  r = no2Chemistry({ noxInc: 120, noxBg: 40, no2Bg: 25, o3Bg: 45, tau: Infinity, J, k });
  const N = r.nox / PPB.no2, x = r.no2 / PPB.no2, Xo = r.ox;
  assertClose(k * (N - x) * (Xo - x), J * x, 1e-9 * J * x + 1e-15, 'photostationary state');
  // Conservation of NOx and Ox, and tau → 0 gives the mixed initial state
  r = no2Chemistry({ noxInc: 80, noxBg: 30, no2Bg: 18, o3Bg: 40, tau: 60, J, k, fNO2: 0.1 });
  assertClose(r.nox, 110, 1e-9, 'NOx conserved');
  assertClose(r.no2 / PPB.no2 + r.o3 / PPB.o3, 40 / PPB.o3 + 18 / PPB.no2 + 8 / PPB.no2, 1e-9, 'Ox conserved');
  assertClose(r.no2 / PPB.no2 + r.no / PPB.no, 110 / PPB.no2, 1e-9, 'NO + NO2 = NOx (ppb)');
  const r0 = no2Chemistry({ noxInc: 80, noxBg: 30, no2Bg: 18, o3Bg: 40, tau: 0, J, k, fNO2: 0.1 });
  assertClose(r0.no2, 18 + 8, 1e-9, 'τ = 0: background + primary NO2');
  // Rate coefficients and unit factors (critic §1.13)
  assertClose(kNOO3(15), 4.19e-4, 0.02e-4, 'k(15 °C)');
  assertClose(jNO2(800) / 1.05, 8.7e-3, 0.05e-3, 'J(800 W/m²)');
  assertClose(PPB.no2, 1.9125, 1e-4, 'NO2 factor'); assertClose(PPB.no, 1.2474, 1e-4, 'NO factor'); assertClose(PPB.o3, 1.9953, 1e-4, 'O3 factor');
});

test('models: metrics on known vectors (Chang & Hanna 2004)', () => {
  const m = metrics([1, 2, 3, 4], [2, 2, 3, 8]);
  assertClose(m.FB, -0.4, 1e-12, 'FB'); assertClose(m.NMSE, 4.25 / 9.375, 1e-12, 'NMSE');
  assertClose(m.MG, Math.SQRT1_2, 1e-12, 'MG'); assertClose(m.VG, Math.exp(2 * Math.log(0.5) ** 2 / 4), 1e-12, 'VG');
  assertClose(m.FAC2, 1, 1e-12, 'FAC2'); assertClose(m.NAD, 0.2, 1e-12, 'NAD');
  assertClose(m.R, 9.5 / Math.sqrt(5 * 24.75), 1e-12, 'R'); assert(m.n === 4, 'n');
  const p = metrics([5, 10, 20, NaN], [5, 10, 20, 7]);
  assert(p.n === 3 && p.FB === 0 && p.NMSE === 0 && p.MG === 1 && p.VG === 1 && p.FAC2 === 1, 'perfect model');
  assertClose(p.R, 1, 1e-12, 'perfect R');
  const f = metrics([0.2, -3, 50], [0.5, 0.1, 150]);        // both below the 1 µg/m³ floor count as FAC2 hits
  assertClose(f.FAC2, 2 / 3, 1e-12, 'FAC2 with floor');
  assertClose(mqi([10, 20, 30], [10, 20, 30], 'no2'), 0, 1e-12, 'MQI perfect');
});

test('models: trafficFactor weekly mean 1 and profiles normalised', () => {
  const t0 = Date.UTC(2025, 2, 10, 0);                      // hour ending 00:00Z = local Monday 00:00–01:00 (CET)
  let s = 0;
  for (let h = 0; h < 168; h++) s += trafficFactor(t0 + h * 3600e3, { month: false });
  assertClose(s / 168, 1, 1e-12, 'weekly mean');
  for (const k of ['weekday', 'saturday', 'sunday']) assertClose(TRAFFIC_PROFILES.hour[k].reduce((a, b) => a + b, 0), 1, 1e-12, k);
  assertClose(TRAFFIC_PROFILES.day.reduce((a, b) => a + b, 0) / 7, 1, 1e-12, 'day factors');
  assertClose(TRAFFIC_PROFILES.month.reduce((a, v, i) => a + v * EM_MONTH_DAYS[i], 0) / 365, 1, 1e-12, 'month factors');
  let a = 0, n = 0;
  for (let tt = Date.UTC(2025, 0, 1, 1); tt <= Date.UTC(2026, 0, 1, 0); tt += 3600e3) { a += trafficFactor(tt); n++; }
  assertClose(a / n, 1, 0.01, 'annual mean ≈ 1 (holidays lower it slightly)');
  // Weekday peak 08–09 h local start (7.2 %): 2025-03-11 07:00Z hour-ending = 07:00–08:00 local
  assertClose(trafficFactor(Date.UTC(2025, 2, 11, 8), { month: false }), 24 * 0.072 * TRAFFIC_PROFILES.day[1], 1e-12, 'weekday 08 h');
  assert(met_localParts(Date.UTC(2025, 11, 25, 12)).day === 25 && trafficFactor(Date.UTC(2025, 11, 25, 12), { month: false })
    === 24 * TRAFFIC_PROFILES.hour.sunday[12] * TRAFFIC_PROFILES.day[6], 'Christmas uses the Sunday profile');
  return { annualMean: a / n };
});

test('models: local time (EU summer time) and solar elevation', () => {
  let p = met_localParts(Date.UTC(2025, 2, 30, 1));         // hour start 00:00Z = 01:00 CET
  assert(p.hour === 1 && p.offset === 1, 'before the switch');
  p = met_localParts(Date.UTC(2025, 2, 30, 2));             // hour start 01:00Z = 03:00 CEST
  assert(p.hour === 3 && p.offset === 2, 'after the switch');
  p = met_localParts(Date.UTC(2025, 9, 26, 1));             // hour start 00:00Z = 02:00 CEST
  assert(p.hour === 2 && p.offset === 2, 'October, before');
  p = met_localParts(Date.UTC(2025, 9, 26, 2));             // hour start 01:00Z = 02:00 CET
  assert(p.hour === 2 && p.offset === 1, 'October, after');
  const eq = solarElevation(Date.UTC(2025, 2, 20, 11, 4));  // near solar noon at the March equinox
  assertClose(eq, 90 - 45.8, 0.6, 'equinox noon');
  assertClose(solarElevation(Date.UTC(2025, 5, 21, 11, 2)), 90 - 45.8 + 23.44, 0.6, 'solstice noon');
  assert(solarElevation(Date.UTC(2025, 5, 21, 23)) < 0, 'night');
});

test('models: groupStrengths units, heating season and measures', () => {
  const tt = Date.UTC(2025, 2, 11, 8);
  const f = trafficFactor(tt);
  const q = groupStrengths('nox', tt, {}, {});
  assertClose(q.A, 10000 * f / 24 * 0.5 / 3.6e6, 1e-15, 'q_A = unit AADT × EF / 3.6e6');
  assert(q.A === q.B && q.B === q.C && q.D === 0, 'same unit on every road; heating off by default');
  assertClose(groupStrengths('no2', tt).A, q.A, 0, 'NO2 → NOx emission');
  const jan19 = Date.UTC(2025, 0, 15, 19);                  // hour start 18:00Z = 19:00 CET, evening peak
  assertClose(groupStrengths('nox', jan19, {}, { heating: 'auto' }).D, 1e-6, 1e-18, 'heating evening peak');
  assertClose(groupStrengths('pm10', jan19, {}, { heating: 'auto' }).D, 2e-6, 1e-18, 'heating PM10 peak');
  assert(groupStrengths('nox', Date.UTC(2025, 6, 15, 19), {}, { heating: 'auto' }).D === 0, 'no heating in July (auto)');
  assert(groupStrengths('nox', Date.UTC(2025, 6, 15, 19), {}, { heating: true }).D > 0, 'forced heating');
  assert(groupStrengths('nox', tt, { carFreeMiramarska: true }).B === 0, 'car-free Miramarska');
  assert(groupStrengths('nox', tt, { evShare: 100 }).A === 0 && groupStrengths('pm10', tt, { evShare: 100 }).A > 0, 'EVs keep wear PM');
  assertClose(groupStrengths('nox', tt, { evShare: 1 }).A, 0.99 * q.A, 1e-18, 'evShare is a percentage');
  assertClose(groupStrengths('nox', tt, { lez: true }).A, 0.6 * q.A, 1e-18, 'LEZ NOx −40 %');
  assertClose(groupStrengths('nox', tt, { trafficPct: 50, trafficA: 200 }).A, q.A, 1e-18, 'traffic multipliers');
  const qc = groupStrengths('nox', tt, { congestion: true }, { congestionShare: { A: 0.4, B: 1 } });
  assertClose(qc.A, q.A * (1 + 1.5 * 0.4), 1e-18, 'congestion A'); assertClose(qc.B, q.B * 2.5, 1e-18, 'congestion B');
  assert(qc.C === q.C, 'no congestion on group C');
  assert(groupStrengths('o3', tt).A === 0, 'no O3 emission');
  const pm = groupStrengths('pm10', tt), pmR = groupStrengths('pm10', tt, { resuspension: true });
  assertClose(pmR.A / pm.A, (0.046 + 0.056) / 0.046, 1e-9, 'winter sanding adds AP-42 resuspension');
});

test('models: ReceptorModel with a synthetic LUT, live-field override and fallback', () => {
  const g = (j, c, k) => 0.01 * (j + 1) * (k + 1) * (c + 1);
  const lut = { dirs: DIRS16, classes: ['AC', 'D', 'EF'], groups: ['A', 'B', 'C', 'D'],
    gamma: DIRS16.map((_, j) => [0, 1, 2].map((c) => [0, 1, 2, 3].map((k) => g(j, c, k)))),
    age: DIRS16.map((_, j) => [0, 1, 2].map((c) => [0, 1, 2, 3].map((k) => 50 * g(j, c, k)))),
    band: DIRS16.map((_, j) => [0, 1, 2].map((c) => [0, 1, 2, 3].map((k) => [0.8 * g(j, c, k), 1.3 * g(j, c, k)]))) };
  const rm = new ReceptorModel({ lut, cal: { status: 'uncalibrated' }, env: { roads: [] } });
  let r = rm.gammaAt(67.5, 8, 'D');
  const w = directionWeights(67.5, 8);
  const exp0 = DIRS16.reduce((s, _, j) => s + w[j] * g(j, 1, 0), 0);
  assertClose(r.gamma[0], exp0, 1e-9, 'kernel-weighted LUT'); assert(r.source === 'lut' && r.band, 'source lut with band');
  r = rm.gammaAt(10, 0.2, 'F');                             // calm: uniform mean over directions, group EF
  assertClose(r.gamma[3], DIRS16.reduce((s, _, j) => s + g(j, 2, 3), 0) / 16, 1e-9, 'calm mean');
  // A live field replaces the LUT for its own direction only (weight w[3] ≈ 0.40 at σθ = 22.5°).
  rm.setField('today', 3, 'D', { gamma: [9, 9, 9, 9], age: [1, 1, 1, 1] });
  r = rm.gammaAt(67.5, 8, 'D');
  assertClose(r.coverage, w[3], 1e-6, 'coverage = kernel weight of the field direction');
  assertClose(r.gamma[0], exp0 - w[3] * g(3, 1, 0) + w[3] * 9, 1e-9, 'field replaces its direction');
  assert(r.source === 'lut' && r.parts.field && r.parts.lut, 'mixed parts, LUT has the larger weight');
  for (let j = 0; j < 16; j++) rm.setField('today', j, 'D', { gamma: [1, 1, 1, 1], age: [5, 5, 5, 5] });
  r = rm.gammaAt(67.5, 8, 'D');
  assert(r.source === 'field' && Math.abs(r.coverage - 1) < 1e-6 && Math.abs(r.gamma[2] - 1) < 1e-6, 'all directions live');
  const s = rm.gammaAt(67.5, 8, 'D', 'tower');             // another scenario falls back to today's fields
  assert(s.coverage === 0 && Math.abs(s.gamma[0] - 1) < 1e-6, 'scenario falls back to today');
  rm.setField('tower', 3, 'D', { receptor: () => ({ gamma: [2, 2, 2, 2], age: [0, 0, 0, 0] }) });
  assertClose(rm.gammaAt(67.5, 8, 'D', 'tower').coverage, w[3], 1e-6, 'ScalarField-like object accepted');
  rm.clearFields();
  assert(rm.gammaAt(67.5, 8, 'D').source === 'lut', 'cleared');
  const noLut = new ReceptorModel({ lut: null, env: { roads: [{ p: [[-100, 20], [100, 20]], g: 'A', aadt: 20000, w: 10 }] } });
  r = noLut.gammaAt(180, 3, 'D');
  assert(r.source === 'fallback' && r.gamma[0] > 0, 'fallback when LUT is null');
});

/*
 * Integration rule (model.js "Grid consistency"): a live field on another grid than LUT.meta.grid never replaces
 * the calibrated LUT for 'today'; a scenario field on that grid is carried onto the LUT as a relative change
 * against the same-grid 'today' field (mod_deltaOnLut). Fields on the LUT's grid, or without a grid, behave as before.
 */
// directionWeights() returns a Float32Array, so kernel-weighted sums carry float32 rounding (~1e-7 relative).
const MT_F32 = 1e-6;
test('models: live fields on another grid than the LUT (delta method)', () => {
  const lutG = [0.01, 0.4, 0.03, 1.2];
  const lut = { meta: { grid: '60x60x16@10m' }, dirs: DIRS16, classes: ['AC', 'D', 'EF'], groups: ['A', 'B', 'C', 'D'],
    gamma: DIRS16.map(() => [0, 1, 2].map(() => lutG.slice())), age: DIRS16.map(() => [0, 1, 2].map(() => lutG.map((v) => 30 * v))),
    band: DIRS16.map(() => [0, 1, 2].map(() => lutG.map((v) => [0.5 * v, 2 * v]))) };
  const rm = new ReceptorModel({ lut, cal: { status: 'uncalibrated' }, env: { roads: [] } });
  const all = (scen, gamma, grid) => { for (let j = 0; j < 16; j++) rm.setField(scen, j, 'D', { gamma, age: gamma.map((v) => 20 * v), grid }); };
  // today on 5 m: ignored next to a 10 m LUT
  all('today', [0.004, 0.2, 0.02, 0.4], '120x120x32@5m');
  let r = rm.gammaAt(45, 1.7, 'D');
  assert(r.source === 'lut' && r.coverage === 0, 'a 5 m today field does not replace the 10 m LUT');
  lutG.forEach((v, k) => assertClose(r.gamma[k], v, MT_F32, `LUT kept, group ${k}`));
  // scenario on 5 m: Miramarska −25 % and heating +10 % relative to today's 5 m field; Vukovarska (below the 5 % share
  // of today's response) gets the absolute change scaled by ΣL/Σt
  all('trees', [0.006, 0.15, 0.02, 0.44], '120x120x32@5m');
  r = rm.gammaAt(45, 1.7, 'D', 'trees');
  assertClose(r.coverage, 1, 1e-6, 'scenario coverage');
  assertClose(r.gamma[1], 0.4 * 0.75, MT_F32, 'relative change carried onto the LUT');
  assertClose(r.gamma[3], 1.2 * 1.1, MT_F32, 'heating relative change');
  const scale = lutG.reduce((a, b) => a + b, 0) / (0.004 + 0.2 + 0.02 + 0.4);
  assertClose(r.gamma[0], 0.01 + 0.002 * scale, MT_F32, 'additive change for a small group');
  assert(r.band && Math.abs(r.band[1][1] - 2 * r.gamma[1]) < MT_F32, 'band scaled with the LUT entry');
  // same grid as the LUT: fields are used as they are (the software-WebGL case, 10 m everywhere)
  all('today', [1, 1, 1, 1], '60x60x16@10m');
  r = rm.gammaAt(45, 1.7, 'D');
  assert(r.source === 'field' && Math.abs(r.gamma[2] - 1) < MT_F32, 'same-grid today field replaces the LUT');
  rm.clearFields();
  all('tower', [2, 2, 2, 2], '120x120x32@5m');                  // no same-grid today field: used as it is
  assertClose(rm.gammaAt(45, 1.7, 'D', 'tower').gamma[0], 2, MT_F32, 'scenario field without a today twin');
});

test('models: increment, concentrations and cellValue agree', () => {
  const ga = { gamma: [0.05, 0.3, 0.1, 0.2], age: [2, 12, 8, 30], source: 'lut' };
  const tt = Date.UTC(2025, 0, 14, 8);
  const q = groupStrengths('nox', tt, {}, { heating: 'auto' });
  const inc = increment(ga, q, 1.5, { beta: 2, U0: 1.4 });
  const U = Math.sqrt(1.5 * 1.5 + 1.4 * 1.4);
  assertClose(inc.total, 1e6 * 2 * (q.A * 0.05 + q.B * 0.3 + q.C * 0.1 + q.D * 0.2) / U, 1e-9, 'ΔC');
  assertClose(inc.tau, (q.A * 2 + q.B * 12 + q.C * 8 + q.D * 30) / (U * (q.A * 0.05 + q.B * 0.3 + q.C * 0.1 + q.D * 0.2)), 1e-9, 'τ');
  const bg = { nox: 30, no2: 20, o3: 35, pm10: 25, pm25: 15, co: 0.2, c6h6: 0.4 };
  const met = { u10: 1.5, dir: 45, sw: 150, cc: 60, t2: 3 };
  const c = concentrations({ met, dateUTC: tt, background: bg, gammaAge: ga, opts: { heating: 'auto', cal: { beta: 2, U0: 1.4 } } });
  assertClose(c.inc.nox, inc.total, 1e-9, 'NOx increment'); assertClose(c.nox, 30 + inc.total, 1e-9, 'NOx total');
  assert(c.no2 <= c.nox && c.no2 >= 0 && c.o3 >= 0, 'NO2 bounded');
  assertClose(c.pm10, 25 + c.inc.pm10, 1e-12, 'PM10 total'); assert(c.co > 0.2 && c.co < 1, 'CO in mg/m³');
  assertClose(c.byGroup.nox.reduce((a, b) => a + b, 0), c.inc.nox, 1e-9, 'groups sum');
  const ctx = sliceContext({ met, dateUTC: tt, background: bg, opts: { heating: 'auto', cal: { beta: 2, U0: 1.4 } } });
  assertClose(cellValue(ga.gamma, ga.age, ctx.strengthsAll, ctx.met, ctx.bg, 'no2'), c.no2, 1e-9, 'cellValue NO2 = receptor NO2');
  assertClose(cellValue(ga.gamma, ga.age, ctx.strengthsAll, ctx.met, ctx.bg, 'pm25'), c.pm25, 1e-9, 'cellValue PM2.5');
  const raw = concentrations({ met, dateUTC: tt, background: bg, gammaAge: ga, opts: { calibrated: false } });
  assert(raw.meta.beta === 1 && raw.meta.status === 'raw', 'raw physics uses β = 1');
  const def = concentrations({ met, dateUTC: tt, gammaAge: ga });
  assert(def.bg.source === 'default' && Number.isFinite(def.no2), 'default background');
  return { no2: c.no2, nox: c.nox, tau: c.inc.tau, band: c.band };
});

test('models: fallback on ENV (speed < 1 s, non-negative, linear in AADT)', () => {
  let t0 = performance.now();
  const fb = new FallbackModel(ENV);
  const build = performance.now() - t0;
  let worst = 0;
  const g = [0, 0, 0, 0];
  for (const d of DIRS16) {
    t0 = performance.now();
    const r = fb.receptor(d, 'D');
    worst = Math.max(worst, performance.now() - t0);
    for (let k = 0; k < 4; k++) { assert(Number.isFinite(r.gamma[k]) && r.gamma[k] >= 0, `Γ finite ≥ 0 (${d}°)`); g[k] += r.gamma[k] / 16; }
  }
  assert(worst < 1000, `receptor() took ${worst} ms`);
  const env2 = { roads: ENV.roads.map((r) => ({ ...r, aadt: 2 * r.aadt })), buildings: [], heating: ENV.heating };
  const a = new FallbackModel({ ...env2, roads: ENV.roads, buildings: [] }).receptor(135, 'D');
  const b = new FallbackModel(env2).receptor(135, 'D');
  for (let k = 0; k < 3; k++) assertClose(b.gamma[k], 2 * a.gamma[k], 1e-9 * a.gamma[k] + 1e-15, `linear in AADT, group ${k}`);
  t0 = performance.now();
  const sl = fb.slice(45, 'D', 4, { x0: -150, z0: -150, dx: 30, nx: 10, nz: 10 });
  const sliceMs = performance.now() - t0;
  assert(sl.every((v) => Number.isFinite(v) && v >= 0), 'slice finite');
  return { points: fb.src.n, buildMs: Math.round(build), worstReceptorMs: Math.round(worst), meanGamma: g, sliceMsPer100Cells: Math.round(sliceMs),
    center: fb.center, canyons: fb.canyons.map((c) => !!c) };
});

test('models: EAQI bands and threshold lines', () => {
  assert(eaqi('no2', 10).level === 1 && eaqi('no2', 10.01).level === 2 && eaqi('no2', 151).level === 6, 'EEA 2024 NO2');
  assert(eaqi('no2', 41, '1h', 'iszz').level === 2 && eaqi('pm10', 55, '24h', 'iszz').level === 4, 'ISZZ legacy');
  assert(eaqi('co', 1).level === 0 && eaqi('no2', NaN).level === 0, 'outside the index / no data');
  assert(eaqi('pm25', 16).color === '#F0E641', 'colour');
  const now = thresholdLines('no2', '1h', { year: 2026 });
  assert(now.some((l) => l.v === 200 && l.kind === 'limit' && l.n === 18) && now.some((l) => l.v === 400 && l.kind === 'alert'), '2026 lines');
  const later = thresholdLines('no2', 'year', { year: 2031, kinds: ['limit'] });
  assert(later.length === 1 && later[0].v === 20, '2030 annual limit');
  assert(thresholdLines('pm10', '24h', { year: 2028 }).some((l) => l.v === 90 && l.kind === 'info'), 'information threshold');
});

// Timing of the CPU map on the tunnel footprint (600 × 600 m). Slow on a loaded machine; skipped with --skip-slow.
test('models: fallback slice timing on ENV (60×60 at 10 m, 120×120 at 5 m)', () => {
  const fb = new FallbackModel(ENV);
  let t0 = performance.now();
  fb._rotated(45);
  const sortMs = performance.now() - t0;
  const out = { points: fb.src.n, sortMs: Math.round(sortMs) };
  for (const [nx, dx] of [[60, 10], [120, 5]]) {
    t0 = performance.now();
    const s = fb.slice(45, 'D', 4, { x0: -300, z0: -300, dx, nx, nz: nx });
    out[`slice${nx}Ms`] = Math.round(performance.now() - t0);
    assert(s.every((v) => Number.isFinite(v) && v >= 0), 'finite');
  }
  t0 = performance.now();
  for (const d of DIRS16) fb.receptor(d + 0.1, 'F');
  out.receptor16Ms = Math.round(performance.now() - t0);
  return out;
}, { slow: true });
